    la   t0, k3_irq_count
    lw   t2, 0(t0)                # handled
    bne  t1, t2, k3_bad
    beq  t1, x0, k3_bad           # ...and at least one, so
                                  # the check is not vacuous
    RVTEST_PASS

k3_bad:
    RVTEST_FAIL

    # ---- CLINT msip handler (IVT slot 83, hardware-vectored,
    # legacy delivery).  Clears the LEVEL before iret or the
    # handler re-triggers immediately.  t0/t1/t2 are saved so
    # the stream's pool registers are untouched.
k3_msip_isr:
    addi sp, sp, -12
    sw   t0, 0(sp)
    sw   t1, 4(sp)
    sw   t2, 8(sp)
    li   t0, 0x5000
    sw   x0, 0(t0)                # clear MSIP[0]
    la   t1, k3_irq_count
    lw   t2, 0(t1)
    addi t2, t2, 1
    sw   t2, 0(t1)
    lw   t0, 0(sp)
    lw   t1, 4(sp)
    lw   t2, 8(sp)
    addi sp, sp, 12
    iret

    # ---- extend the env IVT: DEFINE_IVT emitted slots 0-82.
    .section .ivt, "ax"
    .org 0x14C
    jal  zero, k3_msip_isr        # 83 msip
    jal  zero, 0x0BB00            # 84 mtip: parked
    jal  zero, 0x0BB00            # 85 meip: parked
    .previous

    RVTEST_CODE_END

  .data
RVTEST_DATA_BEGIN

  TEST_DATA

RVTEST_DATA_END

